export class WorkerRoleTypeDto implements IWorkerRoleTypeDto {
    byScope!: ByScopeDto[];
    roles!: ByRolesDto[];

    constructor(data?: IWorkerRoleTypeDto) {
        if (data) {
            for (var property in data) {
                if (data.hasOwnProperty(property))
                    (this as any)[property] = (data as any)[property];
            }
        }
        if (!data) {
            this.byScope = [];
            this.roles = [];
        }
    }

    init(_data?: any) {
        if (_data) {
            if (Array.isArray(_data["byScope"])) {
                this.byScope = [] as any;
                for (let item of _data["byScope"])
                    this.byScope!.push(ByScopeDto.fromJS(item));
            }
            if (Array.isArray(_data["roles"])) {
                this.roles = [] as any;
                for (let item of _data["roles"])
                    this.roles!.push(ByRolesDto.fromJS(item));
            }
        }
    }

    static fromJS(data: any): WorkerRoleTypeDto {
        data = typeof data === 'object' ? data : {};
        let result = new WorkerRoleTypeDto();
        result.init(data);
        return result;
    }

    toJSON(data?: any) {
        data = typeof data === 'object' ? data : {};
        if (Array.isArray(this.byScope)) {
            data["byScope"] = [];
            for (let item of this.byScope)
                data["byScope"].push(item ? item.toJSON() : undefined as any);
        }
        if (Array.isArray(this.roles)) {
            data["roles"] = [];
            for (let item of this.roles)
                data["roles"].push(item ? item.toJSON() : undefined as any);
        }
        return data;
    }
}

export interface IWorkerRoleTypeDto {
    byScope: ByScopeDto[];
    roles: ByRolesDto[];
}

export class ApiException extends Error {
    override message: string;
    status: number;
    response: string;
    headers: { [key: string]: any; };
    result: any;

    constructor(message: string, status: number, response: string, headers: { [key: string]: any; }, result: any) {
        super();

        this.message = message;
        this.status = status;
        this.response = response;
        this.headers = headers;
        this.result = result;
    }

    protected isApiException = true;

    static isApiException(obj: any): obj is ApiException {
        return obj.isApiException === true;
    }
}

function throwException(message: string, status: number, response: string, headers: { [key: string]: any; }, result?: any): any {
    throw new ApiException(message, status, response, headers, result);
}

